CREATE TABLE provider_fixture_heads(fixture_id TEXT PRIMARY KEY,observation_id TEXT NOT NULL REFERENCES provider_fixture_observations(id),kickoff_utc TEXT NOT NULL,business_date TEXT NOT NULL,observed_at TEXT NOT NULL,mapping_version TEXT NOT NULL);
CREATE INDEX provider_heads_time ON provider_fixture_heads(kickoff_utc,observed_at);
INSERT INTO provider_fixture_heads SELECT fixture_id,id,kickoff_utc,business_date,observed_at,json_extract(payload,'$.mapping_version') FROM (SELECT *,ROW_NUMBER() OVER(PARTITION BY fixture_id ORDER BY observed_at DESC,id DESC) choice FROM provider_fixture_observations) WHERE choice=1;
CREATE TRIGGER provider_head_after_insert AFTER INSERT ON provider_fixture_observations BEGIN INSERT INTO provider_fixture_heads VALUES(NEW.fixture_id,NEW.id,NEW.kickoff_utc,NEW.business_date,NEW.observed_at,json_extract(NEW.payload,'$.mapping_version')) ON CONFLICT(fixture_id) DO UPDATE SET observation_id=excluded.observation_id,kickoff_utc=excluded.kickoff_utc,business_date=excluded.business_date,observed_at=excluded.observed_at,mapping_version=excluded.mapping_version WHERE excluded.observed_at>=provider_fixture_heads.observed_at; END;
